syntax:
if (condition1) {
    // runs only if condition1 is true
} else if (condition2) {
    // runs only if condition1 was false AND condition2 is true
} else if (condition3) {
    // runs only if 1 and 2 were false AND condition3 is true
} else {
    // runs only if none of the conditions above was true
}
// only ONE block runs, then the program continues here

