#include <iostream>
using namespace std;

int main() {
    int marks;
    cin >> marks;
    if (marks >= 85) {
        cout << "Grade: A" << endl;
    } else if (marks >= 70) {
        cout << "Grade: B" << endl;
    } else if (marks >= 60) {
        cout << "Grade: C" << endl;
    } else {
        cout << "Grade: F" << endl;
    }
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int km;
    cin >> km;
    int fare;
    if (km <= 2) {
        fare = 100;
    } else if (km <= 5) {
        fare = 150;
    } else if (km <= 10) {
        fare = 250;
    } else {
        fare = 250 + (km - 10) * 30;
    }
    cout << "Fare: Rs " << fare << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int units;
    cin >> units;
    double bill;
    if (units < 0) {
        cout << "Invalid units" << endl;
    } else if (units <= 100) {
        bill = units * 10;
        cout << "Bill: Rs " << bill << endl;
    } else if (units <= 200) {
        bill = 100 * 10 + (units - 100) * 15;
        cout << "Bill: Rs " << bill << endl;
    } else {
        bill = 100 * 10 + 100 * 15 + (units - 200) * 20;
        cout << "Bill: Rs " << bill << endl;
    }
    return 0;
}

